#include <stdio.h>
/* ex02：海明码——用 3 个校验位保护 4 个数据位
 * 校验位放在 2 的幂次位置（1、2、4、8...），每个校验位负责
 * 「位置编号的二进制中该位为 1」的那些位。
 *   1 号位 负责 1,3,5,7
 *   2 号位 负责 2,3,6,7
 *   4 号位 负责 4,5,6,7
 * 数据位依次填在 3,5,6,7。接收端重算校验位，得到「指误字」，
 * 其值就是出错位的编号 —— 所以海明码能纠 1 位错。*/
int main(void) {
    int d[5] = {0, 1, 0, 1, 1};       /* d[1..4] = 1 0 1 1 */
    int c[8] = {0};                   /* c[1..7] 为最终 7 位码字 */

    c[3] = d[1]; c[5] = d[2]; c[6] = d[3]; c[7] = d[4];

    c[1] = c[3] ^ c[5] ^ c[7];        /* 负责 1,3,5,7 */
    c[2] = c[3] ^ c[6] ^ c[7];        /* 负责 2,3,6,7 */
    c[4] = c[5] ^ c[6] ^ c[7];        /* 负责 4,5,6,7 */

    printf("数据位: %d%d%d%d（放在位置 3,5,6,7）\n", d[1], d[2], d[3], d[4]);
    printf("--------------------------------------------------\n");
    printf("校验位计算:\n");
    printf("  P1 = d3^d5^d7 = %d    （负责位置 1,3,5,7）\n", c[1]);
    printf("  P2 = d3^d6^d7 = %d    （负责位置 2,3,6,7）\n", c[2]);
    printf("  P4 = d5^d6^d7 = %d    （负责位置 4,5,6,7）\n", c[4]);
    printf("海明码（位置 1..7）: ");
    for (int i = 1; i <= 7; i++) printf("%d", c[i]);
    printf("\n");

    /* 纠错演示：故意把第 5 位翻转 */
    printf("\n纠错演示：让第 5 位出错（0 -> 1）\n");
    c[5] ^= 1;
    printf("接收到的码字: ");
    for (int i = 1; i <= 7; i++) printf("%d", c[i]);
    printf("\n");

    int s1 = c[1] ^ c[3] ^ c[5] ^ c[7];
    int s2 = c[2] ^ c[3] ^ c[6] ^ c[7];
    int s4 = c[4] ^ c[5] ^ c[6] ^ c[7];
    int syn = s4 * 4 + s2 * 2 + s1 * 1;
    printf("指误字 = s4 s2 s1 = %d%d%d = %d（十进制）\n", s4, s2, s1, syn);

    if (syn == 0) {
        printf("指误字为 0 -> 无差错\n");
    } else {
        printf("指误字 = %d -> 第 %d 位出错，翻转它即可纠正\n", syn, syn);
        c[syn] ^= 1;
        printf("纠正后: ");
        for (int i = 1; i <= 7; i++) printf("%d", c[i]);
        printf("\n");
    }
    printf("\n结论：海明码的「指误字」直接就是出错位编号，所以能纠 1 位错；\n");
    printf("      但如果错 2 位，指误字会指向一个「看起来像出错」的第三位 —— 越纠越错。\n");
    return 0;
}
